package com.shelf.launcher.ui

// GENERATED by tools/themes/gen_pack_prelude.py from scenes/_prelude.agsl and _reactive.agsl - edit those, then re-run.

/** The shared shader text custom packs are built on (see CustomPackRules.buildSource). */
internal object CustomPackShaders {
    const val PRELUDE = """// Shared by every scene. AGSL (Android 13+), written in the GLSL ES 1.0 subset so the same text
// also runs in the WebGL preview (tools/themes/preview.html): constant loop bounds, no arrays,
// no integer %, no derivatives.
uniform float2 uRes;     // size in pixels
uniform float uTime;     // seconds, wrapped every hour
uniform float4 uBg;      // theme background
uniform float4 uSurf;    // theme surface
uniform float4 uAcc;     // theme accent
uniform float4 uSec;     // theme secondary
uniform float uLod;      // 0 = full detail; 1-2 = fewer noise octaves (Low / Lowest background quality)
uniform float uDensity;  // scene editor's particles + 1 (0 = not set: normal amount)

const float PI = 3.14159265;
const float TAU = 6.2831853;

float sat(float x) { return clamp(x, 0.0, 1.0); }
// x squared. Use this, not pow(x, 2.0): pow() of a negative number is undefined on GPUs (NaN, black).
float sqf(float x) { return x * x; }

// Sine-free hashes: stable on mobile GPUs.
float hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }
float hash12(float2 p) {
    float3 p3 = fract(float3(p.x, p.y, p.x) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}
float2 hash22(float2 p) {
    float3 p3 = fract(float3(p.x, p.y, p.x) * float3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx + p3.yz) * p3.zy);
}

float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash12(i);
    float b = hash12(i + float2(1.0, 0.0));
    float c = hash12(i + float2(0.0, 1.0));
    float d = hash12(i + float2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// At reduced resolution (Low / Lowest quality) the finest octaves are smaller than a pixel anyway:
// uLod skips them, and the sum is rescaled so the scene keeps the same brightness and coverage.
float fbm(float2 p) {
    float v = 0.0;
    float a = 0.5;
    float n = max(2.0, 4.0 - uLod);
    for (int i = 0; i < 4; i++) {
        if (float(i) >= n) break;
        v += a * vnoise(p);
        p = p * 2.03 + float2(17.1, 9.2);
        a *= 0.5;
    }
    return v * 0.9375 / (1.0 - 2.0 * a);
}

float fbm3(float2 p) {
    float v = 0.0;
    float a = 0.5;
    float n = max(2.0, 3.0 - uLod);
    for (int i = 0; i < 3; i++) {
        if (float(i) >= n) break;
        v += a * vnoise(p);
        p = p * 2.07 + float2(5.3, 11.7);
        a *= 0.5;
    }
    return v * 0.875 / (1.0 - 2.0 * a);
}

float2x2 rot(float a) { float c = cos(a); float s = sin(a); return float2x2(c, s, -s, c); }

float sdSegment(float2 p, float2 a, float2 b) {
    float2 pa = p - a;
    float2 ba = b - a;
    float h = sat(dot(pa, ba) / max(dot(ba, ba), 1e-6));
    return length(pa - ba * h);
}

float sdRoundBox(float2 p, float2 b, float r) {
    float2 q = abs(p) - b + r;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

// Soft light falloff: 1 at d = 0, about r/d further out.
float glow(float d, float r) { return r / (d + r); }

// One layer of drifting, twinkling points. uv is in screen heights; the layer moves by drift.
float dots(float2 uv, float scale, float2 drift, float density, float size, float seed) {
    float2 p = uv * scale + drift;
    float2 id = floor(p);
    float2 f = fract(p) - 0.5;
    float2 r = hash22(id + seed);
    if (r.x > density * (uDensity > 0.5 ? uDensity - 1.0 : 1.0)) return 0.0;
    float2 o = (hash22(id + seed + 7.31) - 0.5) * 0.6;
    float d = length(f - o);
    float tw = 0.55 + 0.45 * sin(uTime * (0.6 + 1.6 * r.y) + r.x * 40.0);
    return (1.0 - smoothstep(0.0, size, d)) * tw;
}

// Vignette, plus a little noise so dark gradients don't band on 8-bit panels.
float3 finish(float3 col, float2 fc) {
    // A soft highlight shoulder retains the colour of bright neon and fire instead
    // of clipping all three channels to white. Midtones and OLED black stay intact.
    col = max(col, 0.0);
    float peak = max(col.r, max(col.g, col.b));
    float shoulder = max(peak - 0.72, 0.0);
    float mapped = min(peak, 0.72) + shoulder / (1.0 + shoulder / 0.28);
    col *= mapped / max(peak, 0.0001);
    float2 q = fc / uRes;
    float v = 16.0 * q.x * q.y * (1.0 - q.x) * (1.0 - q.y);
    col *= 0.76 + 0.24 * pow(max(v, 0.0), 0.42);
    // Pure black stays pure black (OLED themes).
    float lit = sat(max(col.r, max(col.g, col.b)) * 80.0);
    col += (hash12(fc) - 0.5) / 255.0 * lit;
    return max(col, 0.0);
}
"""

    const val VIZ_EXTRAS = """// --- music helpers (visualizer packs) ---
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }

// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = mix(A, S, 0.5); // keep the third light in the album's own palette
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.34 + 0.14 * sat(lift));
    return col;
}
"""

    /** Plain uniforms a visualizer pack gets on top of the theme ones. */
    val VIZ_UNIFORMS: List<String> = listOf("uBass", "uMid", "uHigh", "uBeatAge", "uPlaying", "uIntensity", "uEqA", "uEqB", "uWaveY", "uWaveH", "uWaveX", "uPlayT", "uBassT", "uMidT", "uHighT")
}
